{
	global:
		keiland_version;
		keiland_menu_*;
		keiland_window_menu_*;
		keiland_context_menu_*;
		keiland_recent_*;
		keiland_titlebar_*;
		keiland_glass_*;
		keiland_network_*;
		keiland_motion_*;
		keiland_scroller_*;
		keiland_gesture_*;
		keiland_preferences_*;
		keiland_desktop_*;
		keiland_audio_*;
		keiland_keyboard_inset_*;
		keiland_edit_*;
		kl_settings_open;
		kl_settings_close;
		kl_settings_get;
		kl_settings_get_int;
		kl_settings_set;
		kl_settings_set_int;
		kl_settings_reset;
		kl_settings_watch;
